import manifest from '../image-variants.json'

type VariantManifest = { images: { source: string, widths: number[] }[] }

const widthsBySource = new Map(
  (manifest as VariantManifest).images.map((image) => [image.source, image.widths]),
)

function variantPath(source: string, width: number) {
  return source.replace(/\.webp$/, `-${width}w.webp`)
}

/**
 * Builds the srcset for a public image whose variants are generated by
 * scripts/generate-image-variants.mjs, so markup and generated files can
 * never drift apart.
 */
export function imageSrcset(source: string) {
  const key = source.replace(/^\//, '')
  const widths = widthsBySource.get(key)
  if (!widths) throw new Error(`No generated variants for ${source}`)
  return widths.map((width) => `/${variantPath(key, width)} ${width}w`).join(', ')
}

/** Smallest generated variant, used as the `src` fallback. */
export function imageFallback(source: string) {
  const key = source.replace(/^\//, '')
  const widths = widthsBySource.get(key)
  if (!widths) throw new Error(`No generated variants for ${source}`)
  return `/${variantPath(key, Math.min(...widths))}`
}

/**
 * Width below which the landing hero and feature rows collapse to a single
 * column. Mirrors the `max-width: 1023px` query in app/assets/css/landing.css.
 */
export const landingStackBreakpoint = 1023

/**
 * `sizes` attribute for a landing illustration: a share of the viewport while
 * the layout is stacked, a fixed column width once it is side by side.
 */
export function landingImageSizes(stackedVw: number, columnPx: number) {
  return `(max-width: ${landingStackBreakpoint}px) ${stackedVw}vw, ${columnPx}px`
}

/**
 * `sizes` for the hero deck posters, each rendered at 46% of the showcase
 * column. Shared so the preload hint and the markup request the same variant.
 */
export const landingPosterSizes = landingImageSizes(45, 304)
